// Derives src/generated/av-depot-precise.ts from the unchanged core src/calculators/av-depot.ts (dcc29a6).
// Only the OUTPUT FORMATTING is changed: depotPair() returns the raw numbers instead of
// formatCurrencyAdaptive() strings (whole euros for |x| ≥ 1.000 €). Every formula, constant,
// schema and the income tax call stay byte-for-byte the core's. test/precise-core.test.ts
// checks the generated file is up to date and that formatting its numbers with the core's
// formatCurrencyAdaptive reproduces the core output exactly.
// Regenerate: node caifudeguo/av-ui/scripts/precise-core.mjs
import { readFileSync, writeFileSync } from 'node:fs'
import process from 'node:process'

const coreUrl = new URL('../../../src/calculators/av-depot.ts', import.meta.url)
const outUrl = new URL('../src/generated/av-depot-precise.ts', import.meta.url)

const REPLACEMENTS = [
  ['from \'../constants/av-depot\'', 'from \'../../../../src/constants/av-depot\''],
  ['import { formatCurrencyAdaptive, parseCurrency, pmt } from \'../utils\'', 'import { parseCurrency, pmt } from \'../../../../src/utils\''],
  ['from \'../utils/calculator\'', 'from \'../../../../src/utils/calculator\''],
  ['from \'./income-tax\'', 'from \'../../../../src/calculators/income-tax\''],
  ['interface DepotPair {\n  avDepot: string\n  normalDepot: string\n}', 'interface DepotPair {\n  avDepot: number\n  normalDepot: number\n}'],
  ['    normalDepot: formatCurrencyAdaptive(normalDepot),\n    avDepot: formatCurrencyAdaptive(avDepot),', '    normalDepot,\n    avDepot,'],
  ['export const avDepot = defineCalculator(', 'export const avDepotPrecise = defineCalculator('],
]

export function generate() {
  let s = readFileSync(coreUrl, 'utf8')
  for (const [from, to] of REPLACEMENTS) {
    const n = s.split(from).length - 1
    if (n !== 1)
      throw new Error(`expected exactly one occurrence of ${JSON.stringify(from)}, found ${n}`)
    s = s.replace(from, to)
  }
  return `// GENERATED by caifudeguo/av-ui/scripts/precise-core.mjs from src/calculators/av-depot.ts (finanzfluss/calculators dcc29a6, AGPL-3.0).\n// Do not edit. Only change vs. the core: amounts are returned as numbers instead of formatCurrencyAdaptive() strings.\n${s}`
}

if (process.argv[1] && import.meta.url.endsWith(process.argv[1].split('/').pop())) {
  writeFileSync(outUrl, generate())
  console.warn('written', outUrl.pathname)
}
